              const fastapiCode = `from fastapi import FastAPI
from pydantic import BaseModel
from typing import List

app = FastAPI(title="SARS Travel Compliance API")

SARS_TRAVEL_BRACKETS = [
    {"limit": 105000, "fixed_cost": 36115, "fuel_cost": 1.430, "maintenance_cost": 0.515},
    {"limit": 210000, "fixed_cost": 63948, "fuel_cost": 1.530, "maintenance_cost": 0.595},
    {"limit": 315000, "fixed_cost": 90565, "fuel_cost": 1.630, "maintenance_cost": 0.665},
    {"limit": 420000, "fixed_cost": 114354, "fuel_cost": 1.750, "maintenance_cost": 0.745},
    {"limit": 525000, "fixed_cost": 138143, "fuel_cost": 2.030, "maintenance_cost": 0.915},
    {"limit": 630000, "fixed_cost": 164760, "fuel_cost": 2.120, "maintenance_cost": 1.075},
    {"limit": 735000, "fixed_cost": 191377, "fuel_cost": 2.210, "maintenance_cost": 1.115},
    {"limit": 800000, "fixed_cost": 217994, "fuel_cost": 2.300, "maintenance_cost": 1.205}, # Capped at R800k
]

@app.post("/api/calculate-travel")
def calculate_travel(value: float, business_km: float, total_annual: float = 32000.0):
    # Capping at R800,000 max statutory limit
    applied_value = min(value, 800000.0)
    
    # Locate appropriate bracket
    bracket = next((b for b in SARS_TRAVEL_BRACKETS if applied_value <= b["limit"]), SARS_TRAVEL_BRACKETS[-1])
    
    fixed_rate = bracket["fixed_cost"] / total_annual
    total_rate_zar = fixed_rate + bracket["fuel_cost"] + bracket["maintenance_cost"]
    
    return {
        "applied_vehicle_value": applied_value,
        "is_capped": value > 800000.0,
        "deemed_rate_per_km": total_rate_zar,
        "total_claim_zar": total_rate_zar * business_km
    }`;

