                              if (!newEtiName || !newEtiAge || !newEtiWage) {
                                showBanner("Please fill in name, age, and wage.");
                                return;
                              }

                              const wage = parseFloat(newEtiWage);
                              const age = parseInt(newEtiAge);
                              const months = parseInt(newEtiMonths);
                              
                              // ETI Calculation logic under Act 26 of 2013
                              let claimed = 0;
                              if (age >= 18 && age <= 29 && wage >= 2000 && wage <= 6500) {
                                if (months <= 12) {
                                  if (wage <= 4500) {
                                    claimed = wage * 0.5;
                                  } else {
                                    claimed = 1500 - 0.75 * (wage - 4500);
                                  }
                                } else {
                                  if (wage <= 4500) {
                                    claimed = wage * 0.25;
                                  } else {
                                    claimed = 750 - 0.375 * (wage - 4500);
                                  }
                                }
                              }

                              const newEmp = {
                                id: 'emp_' + Date.now(),
                                name: newEtiName,
                                age: age,
                                monthlyWage: wage,
                                qualifyingMonths: months,
                                etiClaimed: Math.round(claimed * 100) / 100
                              };

                              setEtiEmployees(prev => [...prev, newEmp]);
                              addAuditLog("ETI Claim Registered", `Registered ETI claim for ${newEtiName} (Age ${age}, wage R ${wage.toLocaleString()}) calculated at R ${claimed.toLocaleString()}.`);
                              showBanner(`ETI claim registered successfully! Amount: R ${Math.round(claimed).toLocaleString()}`);

                              setNewEtiName('');
